parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "intencion": {
      "type": "string",
      "enum": ["consultar_turno", "registrar_turno", "modificar_turno", "eliminar_turno", "aclarar"],
      "description": "Intención clasificada del paciente"
    },
    "confianza": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Confianza de la clasificación entre 0 y 1"
    },
    "resumen": {
      "type": "string",
      "description": "Una frase con lo que pide el paciente"
    },
    "respuesta_aclaracion": {
      "type": "string",
      "description": "Pregunta para el paciente, solo si intencion es aclarar. En los demás casos, cadena vacía"
    }
  },
  "required": ["intencion", "confianza", "resumen", "respuesta_aclaracion"],
  "additionalProperties": false
}

